/**
 * Reads Prism.js core + selected language grammars from node_modules,
 * concatenates them, and writes a TypeScript file exporting the result
 * as a string constant. Run once after installing/updating prismjs.
 *
 * Usage: node cli/scripts/generate-prism-bundle.mjs
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const prismDir = path.join(__dirname, "..", "node_modules", "prismjs");

// Core
const core = fs.readFileSync(path.join(prismDir, "prism.js"), "utf-8");

// Languages — order matters (some depend on others)
const langs = [
  "clike",        // base for c-like languages
  "javascript",
  "typescript",
  "jsx",
  "tsx",
  "python",
  "ruby",
  "rust",
  "go",
  "java",
  "kotlin",
  "swift",
  "css",
  "scss",
  "markup",       // HTML
  "json",
  "yaml",
  "toml",
  "xml",
  "graphql",
  "sql",
  "bash",
  "docker",       // Dockerfile
  "makefile",
  "markdown",
];

let langCode = "";
for (const lang of langs) {
  const file = path.join(prismDir, "components", `prism-${lang}.js`);
  if (fs.existsSync(file)) {
    langCode += fs.readFileSync(file, "utf-8") + "\n";
  } else {
    console.warn(`Warning: prism-${lang}.js not found, skipping`);
  }
}

// Dark theme CSS (OneDark-inspired, matching live view color palette)
const themeCss = `
.token.comment,.token.prolog,.token.doctype,.token.cdata{color:#5c6f8a}
.token.punctuation{color:#8ca1bd}
.token.namespace{opacity:.7}
.token.property,.token.tag,.token.boolean,.token.number,.token.constant,.token.symbol,.token.deleted{color:#f97583}
.token.selector,.token.attr-name,.token.string,.token.char,.token.builtin,.token.inserted{color:#a5d6ff}
.token.operator,.token.entity,.token.url{color:#79c0ff}
.token.atrule,.token.attr-value,.token.keyword{color:#d2a8ff}
.token.function,.token.class-name{color:#79c0ff}
.token.regex,.token.important,.token.variable{color:#ffa657}
.token.important,.token.bold{font-weight:bold}
.token.italic{font-style:italic}
code[class*="language-"],pre[class*="language-"]{color:#e6edf7;background:none;text-shadow:none;font-family:"Cascadia Code","SF Mono",Menlo,monospace;font-size:12px;text-align:left;white-space:pre;word-spacing:normal;word-break:normal;word-wrap:normal;line-height:1.45;tab-size:2}
`;

const output = `// Auto-generated by scripts/generate-prism-bundle.mjs — do not edit manually.
// Run: node cli/scripts/generate-prism-bundle.mjs

export const PRISM_JS = ${JSON.stringify(core + "\n" + langCode)};

export const PRISM_THEME_CSS = ${JSON.stringify(themeCss)};
`;

const outPath = path.join(__dirname, "..", "src", "ui", "prism-bundle.ts");
fs.writeFileSync(outPath, output, "utf-8");
console.log("Generated", outPath, "—", Math.round(output.length / 1024), "KB");
